export default function PhotoSlideshow() {
  const { t } = useLanguage();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);

  // Auto-advance slideshow
  useEffect(() => {
    if (!isPlaying) return;

    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % galleryImages.length);
    }, 4000);

    return () => clearInterval(interval);
  }, [isPlaying]);

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev + 1) % galleryImages.length);
  };

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev - 1 + galleryImages.length) % galleryImages.length);
  };

  const goToSlide = (index: number) => {
    setCurrentIndex(index);
  };

  const currentImage = galleryImages[currentIndex];

  return (
    <section className="py-16 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="font-playfair text-3xl md:text-4xl font-bold text-moroccan-blue mb-4">
            {t('galleryTitle')}
          </h2>
          <p className="text-xl text-gray-600 max-w-2xl mx-auto">
            {t('gallerySubtitle')}
          </p>
          <div className="w-24 h-1 bg-moroccan-gold mx-auto mt-6" />
        </div>

        {/* Main Slideshow */}
        <Card className="relative overflow-hidden mb-8 bg-black">
          <CardContent className="p-0">
            <div className="relative h-[500px] md:h-[600px]">
              <img
                src={currentImage.src}
                alt={currentImage.alt}
                className="w-full h-full object-cover transition-opacity duration-500"
                onError={(e) => {
                  if (currentImage.fallback) {
                    e.currentTarget.src = currentImage.fallback;
                  }
                }}
              />

              {/* Overlay with image info */}
              <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent p-8">
                <h3 className="font-playfair text-2xl md:text-3xl font-bold text-white mb-2">
                  {currentImage.title}
                </h3>
                <p className="text-gray-200 text-lg max-w-2xl">
                  {currentImage.description}
                </p>
              </div>

              {/* Navigation Arrows */}
              <Button
                variant="ghost"
                size="sm"
                className="absolute left-4 top-1/2 -translate-y-1/2 bg-black/50 hover:bg-black/70 text-white"
                onClick={prevSlide}
              >
                <ChevronLeft className="w-6 h-6" />
              </Button>

              <Button
                variant="ghost"
                size="sm"
                className="absolute right-4 top-1/2 -translate-y-1/2 bg-black/50 hover:bg-black/70 text-white"
                onClick={nextSlide}
              >
                <ChevronRight className="w-6 h-6" />
              </Button>

              {/* Play/Pause Button */}
              <Button
                variant="ghost"
                size="sm"
                className="absolute top-4 right-4 bg-black/50 hover:bg-black/70 text-white"
                onClick={() => setIsPlaying(!isPlaying)}
              >
                {isPlaying ? <Pause className="w-5 h-5" /> : <Play className="w-5 h-5" />}
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Thumbnail Navigation */}
        <div className="flex justify-center space-x-4 mb-8">
          {galleryImages.map((image, index) => (
            <button
              key={image.id}
              onClick={() => goToSlide(index)}
              className={`relative overflow-hidden rounded-lg transition-all duration-300 ${
                index === currentIndex 
                  ? 'ring-4 ring-moroccan-gold scale-110' 
                  : 'hover:scale-105 opacity-70 hover:opacity-100'
              }`}
            >
              <img
                src={image.src}
                alt={image.alt}
                className="w-20 h-16 object-cover"
                onError={(e) => {
                  if (image.fallback) {
                    e.currentTarget.src = image.fallback;
                  }
                }}
              />
            </button>
          ))}
        </div>

        {/* Progress Indicators */}
        <div className="flex justify-center space-x-2">
          {galleryImages.map((_, index) => (
            <div
              key={index}
              className={`h-2 rounded-full transition-all duration-300 ${
                index === currentIndex 
                  ? 'w-8 bg-moroccan-gold' 
                  : 'w-2 bg-gray-300'
              }`}
            />
          ))}
        </div>

        {/* Gallery Stats */}
        <div className="text-center mt-12">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 max-w-4xl mx-auto">
            <div className="text-center">
              <div className="text-3xl font-bold text-moroccan-blue mb-2">6</div>
              <div className="text-gray-600">Unique Destinations</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-moroccan-blue mb-2">1000+</div>
              <div className="text-gray-600">Happy Travelers</div>
            </div>
            <div className="text-center">
              <div className="text-3xl font-bold text-moroccan-blue mb-2">5★</div>
              <div className="text-gray-600">Average Rating</div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

client/src/components/review-form.tsx.content:
import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { z } from "zod";
import { insertReviewSchema } from "@shared/schema";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useLanguage } from "@/hooks/useLanguage";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Star, Send } from "lucide-react";

type ReviewFormData = z.infer<typeof insertReviewSchema>;

interface ReviewFormProps {
  activityId: string;
  activityName: string;
  bookingId?: string;
  onSuccess?: () => void;
}

export default function ReviewForm({ activityId, activityName, bookingId, onSuccess }: ReviewFormProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { t } = useLanguage();
  const [rating, setRating] = useState(0);
  const [hoverRating, setHoverRating] = useState(0);

  const form = useForm<ReviewFormData>({
    resolver: zodResolver(insertReviewSchema),
    defaultValues: {
      customerName: "",
      customerEmail: "",
      activityId,
      bookingId: bookingId || "",
      rating: 0,
      title: "",
      comment: "",
    },
  });

  const createReviewMutation = useMutation({
    mutationFn: async (data: ReviewFormData) => {
      return await apiRequest("/api/reviews", {
        method: "POST",
        body: JSON.stringify(data),
      });
    },
    onSuccess: () => {
      toast({
        title: "Review Submitted",
        description: "Thank you for your feedback! Your review is pending approval.",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/reviews"] });
      queryClient.invalidateQueries({ queryKey: [`/api/activities/${activityId}/rating`] });
      form.reset();
      setRating(0);
      onSuccess?.();
    },
    onError: (error) => {
      console.error("Error submitting review:", error);
      toast({
        title: "Error",
        description: "Failed to submit review. Please try again.",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: ReviewFormData) => {
    if (rating === 0) {
      toast({
        title: "Rating Required",
        description: "Please select a star rating before submitting.",
        variant: "destructive",
      });
      return;
    }

    createReviewMutation.mutate({
      ...data,
      rating,
    });
  };

  return (
    <Card className="max-w-2xl mx-auto">
      <CardHeader>
        <CardTitle className="text-moroccan-blue">
          Leave a Review for {activityName}
        </CardTitle>
        <p className="text-gray-600">
          Share your experience to help other travelers
        </p>
      </CardHeader>
      <CardContent>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="customerName"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Your Name</FormLabel>
                    <FormControl>
                      <Input {...field} placeholder="Enter your full name" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="customerEmail"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Email Address</FormLabel>
                    <FormControl>
                      <Input {...field} type="email" placeholder="your@email.com" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Star Rating */}
            <div className="space-y-2">
              <label className="text-sm font-medium">Rating</label>
              <div className="flex items-center space-x-1">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    type="button"
                    className="transition-colors duration-200"
                    onMouseEnter={() => setHoverRating(star)}
                    onMouseLeave={() => setHoverRating(0)}
                    onClick={() => setRating(star)}
                  >
                    <Star
                      className={`w-8 h-8 ${
                        star <= (hoverRating || rating)
                          ? "fill-yellow-400 text-yellow-400"
                          : "text-gray-300"
                      }`}
                    />
                  </button>
                ))}
                <span className="ml-2 text-sm text-gray-600">
                  {rating > 0 && `${rating} out of 5 stars`}
                </span>
              </div>
            </div>

            <FormField
              control={form.control}
              name="title"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Review Title</FormLabel>
                  <FormControl>
                    <Input {...field} placeholder="Summarize your experience" />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="comment"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Your Review</FormLabel>
                  <FormControl>
                    <Textarea
                      {...field}
                      placeholder="Tell us about your experience... What did you enjoy most? Any tips for future travelers?"
                      className="min-h-[120px]"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <Button
              type="submit"
              disabled={createReviewMutation.isPending}
              className="w-full bg-moroccan-blue hover:bg-moroccan-blue/90"
            >
              <Send className="w-4 h-4 mr-2" />
              {createReviewMutation.isPending ? "Submitting..." : "Submit Review"}
            </Button>
          </form>
        </Form>
      </CardContent>
    </Card>
  );
}

client/src/components/review-list.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Star, User, Calendar, CheckCircle } from "lucide-react";
import type { ReviewWithActivity } from "@shared/schema";

interface ReviewListProps {
  activityId?: string;
  showActivityName?: boolean;
  limit?: number;
}

export default function ReviewList({ activityId, showActivityName = false, limit }: ReviewListProps) {

  const { data: reviews = [], isLoading } = useQuery<ReviewWithActivity[]>({
    queryKey: activityId ? ["/api/reviews", { activityId }] : ["/api/reviews"],
    queryFn: async () => {
      const url = activityId ? `/api/reviews?activityId=${activityId}` : "/api/reviews";
      const response = await fetch(url);
      if (!response.ok) throw new Error("Failed to fetch reviews");
      return response.json();
    },
  });

  const displayedReviews = limit ? reviews.slice(0, limit) : reviews;

  const renderStars = (rating: number) => {
    return (
      <div className="flex items-center space-x-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            className={`w-4 h-4 ${
              star <= rating ? "fill-yellow-400 text-yellow-400" : "text-gray-300"
            }`}
          />
        ))}
      </div>
    );
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  if (isLoading) {
    return (
      <div className="space-y-4">
        {[1, 2, 3].map((i) => (
          <Card key={i} className="animate-pulse">
            <CardContent className="p-6">
              <div className="space-y-3">
                <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                <div className="h-3 bg-gray-200 rounded w-1/2"></div>
                <div className="h-16 bg-gray-200 rounded"></div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  if (reviews.length === 0) {
    return (
      <Card>
        <CardContent className="p-8 text-center">
          <Star className="w-12 h-12 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-600 mb-2">No Reviews Yet</h3>
          <p className="text-gray-500">
            Be the first to share your experience with this activity!
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-xl font-semibold text-moroccan-blue">
          Customer Reviews ({reviews.length})
        </h3>
      </div>

      <div className="space-y-4">
        {displayedReviews.map((review) => (
          <Card key={review._id} className="border-l-4 border-l-moroccan-gold">
            <CardContent className="p-6">
              <div className="space-y-4">
                {/* Header */}
                <div className="flex items-start justify-between">
                  <div className="space-y-2">
                    <div className="flex items-center space-x-3">
                      <div className="flex items-center space-x-2">
                        <User className="w-4 h-4 text-gray-500" />
                        <span className="font-medium text-gray-900">{review.customerName}</span>
                      </div>
                      {(review as any).verified && (
                        <Badge variant="secondary" className="bg-green-100 text-green-800">
                          <CheckCircle className="w-3 h-3 mr-1" />
                          Verified
                        </Badge>
                      )}
                    </div>
                    <div className="flex items-center space-x-4">
                      {renderStars(review.rating)}
                      <div className="flex items-center text-sm text-gray-500">
                        <Calendar className="w-4 h-4 mr-1" />
                        {formatDate(review.createdAt.toString())}
                      </div>
                    </div>
                  </div>
                  {showActivityName && review.activity && (
                    <Badge variant="outline" className="text-moroccan-blue border-moroccan-blue">
                      {review.activity.name}
                    </Badge>
                  )}
                </div>

                {/* Review Content */}
                <div className="space-y-2">
                  <h4 className="font-semibold text-gray-900">{(review as any).title || 'Review'}</h4>
                  <p className="text-gray-700 leading-relaxed">{review.comment}</p>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

client/src/components/security-wrapper.t.content:
import { useEffect, useState, ReactNode } from 'react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { 
  Shield, 
  ShieldAlert, 
  ShieldCheck, 
  Lock, 
  Unlock,
  Eye,
  EyeOff,
  AlertTriangle,
  CheckCircle,
  Clock,
  Wifi
} from 'lucide-react';
import { useSecurity } from '@/hooks/use-security';
import { useToast } from '@/hooks/use-toast';

interface SecurityWrapperProps {
  children: ReactNode;
  requireSecureConnection?: boolean;
  showSecurityStatus?: boolean;
  enableThreatDetection?: boolean;
  logPageView?: boolean;
}

export default function SecurityWrapper({
  children,
  requireSecureConnection = false,
  showSecurityStatus = false,
  enableThreatDetection = true,
  logPageView = true
}: SecurityWrapperProps) {
  const { 
    isSecureConnection, 
    securityLevel, 
    rateLimitRemaining,
    logSecurityEvent 
  } = useSecurity();
  const { toast } = useToast();

  const [securityThreats, setSecurityThreats] = useState<string[]>([]);
  const [showSecurityPanel, setShowSecurityPanel] = useState(false);
  const [connectionAttempts, setConnectionAttempts] = useState(0);

  // Log page view for security audit
  useEffect(() => {
    if (logPageView) {
      logSecurityEvent('page_view', {
        path: window.location.pathname,
        referrer: document.referrer,
        timestamp: new Date().toISOString()
      });
    }
  }, [logSecurityEvent, logPageView]);

  // Monitor for suspicious activity
  useEffect(() => {
    if (!enableThreatDetection) return;

    // Disable threat detection in development mode
    if (process.env.NODE_ENV === 'development') {
      return;
    }

    const detectThreats = () => {
      const threats: string[] = [];

      // Check for multiple rapid clicks (potential bot activity)
      let clickCount = 0;
      const clickHandler = () => {
        clickCount++;
        if (clickCount > 20) { // More than 20 clicks per second
          threats.push('Rapid clicking detected - potential bot activity');
          logSecurityEvent('threat_detected', { type: 'rapid_clicking', count: clickCount });
        }
      };

      // Check for console access (potential script injection)
      const originalConsole = console.log;
      console.log = (...args) => {
        if (args.some(arg => typeof arg === 'string' && arg.includes('script'))) {
          threats.push('Console script activity detected');
          logSecurityEvent('threat_detected', { type: 'console_script_access' });
        }
        originalConsole.apply(console, args);
      };

      // Check for developer tools - disabled in development
      let devtools = false;
      setInterval(() => {
        if (window.outerHeight - window.innerHeight > 200 || 
            window.outerWidth - window.innerWidth > 200) {
          if (!devtools) {
            devtools = true;
            threats.push('Developer tools opened');
            logSecurityEvent('threat_detected', { type: 'devtools_opened' });
          }
        } else {
          devtools = false;
        }
      }, 1000);

      document.addEventListener('click', clickHandler);
      setSecurityThreats(threats);

      return () => {
        document.removeEventListener('click', clickHandler);
        console.log = originalConsole;
      };
    };

    const cleanup = detectThreats();
    return cleanup;
  }, [enableThreatDetection, logSecurityEvent]);

  // Monitor connection attempts
  useEffect(() => {
    const monitorConnections = () => {
      const attempts = connectionAttempts + 1;
      setConnectionAttempts(attempts);

      if (attempts > 5) {
        logSecurityEvent('suspicious_connection_attempts', { count: attempts });
        toast({
          title: "Security Alert",
          description: "Multiple connection attempts detected",
          variant: "destructive",
        });
      }
    };

    window.addEventListener('focus', monitorConnections);
    return () => window.removeEventListener('focus', monitorConnections);
  }, [connectionAttempts, logSecurityEvent, toast]);

  // Block access if secure connection required but not available
  if (requireSecureConnection && !isSecureConnection) {
    return (
      <div className="min-h-screen bg-red-50 flex items-center justify-center p-4">
        <Card className="max-w-md w-full border-red-200">
          <CardHeader>
            <CardTitle className="flex items-center text-red-700">
              <ShieldAlert className="w-6 h-6 mr-2" />
              Secure Connection Required
            </CardTitle>
          </CardHeader>
          <CardContent>
            <Alert className="border-red-200 bg-red-50">
              <Lock className="h-4 w-4" />
              <AlertDescription className="text-red-800">
                This page requires a secure HTTPS connection. Please access this site using HTTPS.
              </AlertDescription>
            </Alert>
            <div className="mt-4 space-y-2">
              <p className="text-sm text-red-600">Security measures:</p>
              <ul className="text-xs text-red-600 space-y-1">
                <li>• SSL/TLS encryption required</li>
                <li>• Data transmission protection</li>
                <li>• Session security enforcement</li>
              </ul>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  const getSecurityLevelColor = (level: string) => {
    switch (level) {
      case 'high': return 'text-green-600 bg-green-100';
      case 'medium': return 'text-yellow-600 bg-yellow-100';
      case 'low': return 'text-red-600 bg-red-100';
      default: return 'text-gray-600 bg-gray-100';
    }
  };

  const getSecurityIcon = (level: string) => {
    switch (level) {
      case 'high': return <ShieldCheck className="w-4 h-4" />;
      case 'medium': return <Shield className="w-4 h-4" />;
      case 'low': return <ShieldAlert className="w-4 h-4" />;
      default: return <Shield className="w-4 h-4" />;
    }
  };

  return (
    <div className="relative">
      {/* Security Status Bar - Hidden but monitoring continues */}
      {false && showSecurityStatus && (
        <div className="bg-gray-50 border-b border-gray-200 px-4 py-2">
          <div className="flex items-center justify-between max-w-7xl mx-auto">
            <div className="flex items-center space-x-4">
              <Badge className={`${getSecurityLevelColor(securityLevel)} border-0`}>
                {getSecurityIcon(securityLevel)}
                <span className="ml-1">Security: {securityLevel.toUpperCase()}</span>
              </Badge>

              <div className="flex items-center space-x-2">
                {isSecureConnection ? (
                  <div className="flex items-center text-green-600">
                    <Lock className="w-4 h-4 mr-1" />
                    <span className="text-xs">Secure</span>
                  </div>
                ) : (
                  <div className="flex items-center text-red-600">
                    <Unlock className="w-4 h-4 mr-1" />
                    <span className="text-xs">Insecure</span>
                  </div>
                )}
              </div>

              <div className="flex items-center space-x-2">
                <Wifi className="w-4 h-4 text-blue-600" />
                <span className="text-xs text-gray-600">
                  Rate limit: {rateLimitRemaining}/100
                </span>
              </div>
            </div>

            <Button
              variant="outline"
              size="sm"
              onClick={() => setShowSecurityPanel(!showSecurityPanel)}
              className="text-xs"
            >
              {showSecurityPanel ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
              <span className="ml-1">Security Panel</span>
            </Button>
          </div>
        </div>
      )}

      {/* Security Panel - Hidden but monitoring continues */}
      {false && showSecurityPanel && (
        <div className="bg-white border-b border-gray-200 px-4 py-4">
          <div className="max-w-7xl mx-auto">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Card className="border-blue-200">
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm flex items-center text-blue-700">
                    <Shield className="w-4 h-4 mr-2" />
                    Connection Security
                  </CardTitle>
                </CardHeader>
                <CardContent className="text-xs space-y-2">
                  <div className="flex justify-between">
                    <span>Protocol:</span>
                    <Badge variant={isSecureConnection ? "default" : "destructive"}>
                      {window.location.protocol.toUpperCase()}
                    </Badge>
                  </div>
                  <div className="flex justify-between">
                    <span>Encryption:</span>
                    <span className={isSecureConnection ? "text-green-600" : "text-red-600"}>
                      {isSecureConnection ? "TLS/SSL" : "None"}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span>Security Level:</span>
                    <Badge className={getSecurityLevelColor(securityLevel)}>
                      {securityLevel.toUpperCase()}
                    </Badge>
                  </div>
                </CardContent>
              </Card>

              <Card className="border-yellow-200">
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm flex items-center text-yellow-700">
                    <Clock className="w-4 h-4 mr-2" />
                    Rate Limiting
                  </CardTitle>
                </CardHeader>
                <CardContent className="text-xs space-y-2">
                  <div className="flex justify-between">
                    <span>Requests Remaining:</span>
                    <span className={rateLimitRemaining < 20 ? "text-red-600" : "text-green-600"}>
                      {rateLimitRemaining}/100
                    </span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2">
                    <div
                      className={`h-2 rounded-full transition-all duration-300 ${
                        rateLimitRemaining < 20 ? 'bg-red-500' : 'bg-green-500'
                      }`}
                      style={{ width: `${rateLimitRemaining}%` }}
                    ></div>
                  </div>
                  <div className="flex justify-between">
                    <span>Reset Time:</span>
                    <span className="text-gray-600">1 minute</span>
                  </div>
                </CardContent>
              </Card>

              <Card className="border-red-200">
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm flex items-center text-red-700">
                    <AlertTriangle className="w-4 h-4 mr-2" />
                    Threat Detection
                  </CardTitle>
                </CardHeader>
                <CardContent className="text-xs space-y-2">
                  {securityThreats.length > 0 ? (
                    <div className="space-y-1">
                      {securityThreats.slice(0, 3).map((threat, index) => (
                        <div key={index} className="text-red-600 text-xs">
                          • {threat}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="flex items-center text-green-600">
                      <CheckCircle className="w-4 h-4 mr-1" />
                      <span>No threats detected</span>
                    </div>
                  )}
                  <div className="flex justify-between">
                    <span>Connection Attempts:</span>
                    <span className={connectionAttempts > 3 ? "text-red-600" : "text-green-600"}>
                      {connectionAttempts}
                    </span>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      )}

      {/* Security Alerts - Hidden but monitoring continues */}
      {false && securityThreats.length > 0 && (
        <div className="bg-red-50 border-b border-red-200 px-4 py-2">
          <div className="max-w-7xl mx-auto">
            <Alert className="border-red-200 bg-red-50">
              <AlertTriangle className="h-4 w-4 text-red-600" />
              <AlertDescription className="text-red-800">
                {securityThreats.length} security threat(s) detected. Please review your activity.
              </AlertDescription>
            </Alert>
          </div>
        </div>
      )}

      {/* Main Content */}
      <div className="relative">
        {children}
      </div>
    </div>
  );
}

