            </Card>
          </div>

          <Tabs defaultValue="bookings" className="space-y-6">
            <TabsList className={`grid w-full ${user?.role === 'superadmin' ? 'grid-cols-7' : 'grid-cols-5'}`}>
              <TabsTrigger value="bookings">Bookings</TabsTrigger>
